  // Menu controls
  (function() {
    const dropBtn = document.getElementById('dropdownBtn');
    const dropMenu = document.getElementById('dropdownMenu');
    const closeBtn = document.getElementById('menuCloseBtn');
    const backdrop = document.getElementById('navBackdrop');
    function open() { if (!dropMenu) return; dropMenu.classList.add('open'); if (dropBtn) { dropBtn.classList.add('active'); dropBtn.setAttribute('aria-expanded','true'); } }
    function close() { if (!dropMenu) return; dropMenu.classList.remove('open'); if (dropBtn) { dropBtn.classList.remove('active'); dropBtn.setAttribute('aria-expanded','false'); } }
    if (dropBtn) dropBtn.addEventListener('click', e => { e.stopPropagation(); dropMenu.classList.contains('open') ? close() : open(); });
    if (closeBtn) closeBtn.addEventListener('click', close);
    if (backdrop) backdrop.addEventListener('click', close);
    if (dropMenu) dropMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', close));
    window.addEventListener('scroll', () => { if (window.scrollY > 20) close(); }, { passive: true });
  })();

  // Hero scroll cue — hide once the page scrolls, reappear back at the hero
  (function() {
    const cue = document.querySelector('.team-hero__scroll');
    if (!cue) return;
    const onScroll = () => {
      cue.style.opacity = window.scrollY > 40 ? '0' : '';
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  })();

  // Lightbox
  (function() {
    const lb = document.getElementById('teamLightbox');
    const lbImg = document.getElementById('lbImg');
    const lbClose = document.getElementById('lbClose');
    const lbPrev = document.getElementById('lbPrev');
    const lbNext = document.getElementById('lbNext');
    let images = [], current = 0;

    document.querySelectorAll('.ig-mini__grid-item').forEach(item => {
      item.addEventListener('click', () => {
        const grid = item.closest('.ig-mini__grid');
        images = Array.from(grid.querySelectorAll('.ig-mini__grid-item')).map(i => i.dataset.src);
        current = Array.from(grid.querySelectorAll('.ig-mini__grid-item')).indexOf(item);
        open(current);
      });
    });

    function open(i) {
      lbImg.src = images[i];
      lb.classList.add('open');
      document.body.style.overflow = 'hidden';
    }
    function close() {
      lb.classList.remove('open');
      document.body.style.overflow = '';
    }
    lbClose.addEventListener('click', close);
    lb.addEventListener('click', e => { if (e.target === lb) close(); });
    lbPrev.addEventListener('click', () => { current = (current - 1 + images.length) % images.length; lbImg.src = images[current]; });
    lbNext.addEventListener('click', () => { current = (current + 1) % images.length; lbImg.src = images[current]; });
    document.addEventListener('keydown', e => {
      if (!lb.classList.contains('open')) return;
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowLeft') { current = (current - 1 + images.length) % images.length; lbImg.src = images[current]; }
      if (e.key === 'ArrowRight') { current = (current + 1) % images.length; lbImg.src = images[current]; }
    });
  })();

// People popup
const peoplePopup = document.getElementById('peoplePopup');
document.querySelectorAll('.people-card').forEach(card => {
  card.addEventListener('click', () => {
    document.getElementById('popupAvatar').textContent = card.dataset.initial;
    document.getElementById('popupPeopleName').textContent = card.dataset.name;
    document.getElementById('popupPeopleRole').textContent = card.dataset.role;
    document.getElementById('popupPeopleBio').textContent = card.dataset.bio;
    peoplePopup.classList.add('open');
    document.body.style.overflow = 'hidden';
  });
});
document.getElementById('peoplePopupClose').addEventListener('click', () => {
  peoplePopup.classList.remove('open');
  document.body.style.overflow = '';
});
peoplePopup.addEventListener('click', e => {
  if (e.target === peoplePopup) { peoplePopup.classList.remove('open'); document.body.style.overflow = ''; }
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && peoplePopup.classList.contains('open')) { peoplePopup.classList.remove('open'); document.body.style.overflow = ''; }
});
